CREATE TABLE families (
    id TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL,
    invite_code TEXT NOT NULL UNIQUE,
    created_at TEXT NOT NULL
);
INSERT INTO "families" VALUES('9fa8e5a4-e42d-42b5-bdfa-c82e19a89e64','Demo family','JKGDXYNF','2026-10-23T23:59:44.206954+00:00');
CREATE TABLE family_invites (
    id TEXT PRIMARY KEY NOT NULL,
    family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    -- hex SHA-256 of the invite secret; the secret itself is only ever in the invite link.
    secret_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'parent',
    -- Caregiver access length from redemption (NULL = no end).
    access_hours INTEGER,
    label TEXT,
    created_by TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    used_at TEXT,
    used_by TEXT REFERENCES users(id) ON DELETE SET NULL,
    revoked_at TEXT
);
CREATE TABLE family_members (
    family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role TEXT NOT NULL DEFAULT 'parent',
    joined_at TEXT NOT NULL, expires_at TEXT,
    PRIMARY KEY (family_id, user_id)
);
INSERT INTO "family_members" VALUES('9fa8e5a4-e42d-42b5-bdfa-c82e19a89e64','d91b1a18-0733-4aff-a2a0-c99506fb7d90','parent','2026-10-23T23:59:44.206954+00:00',NULL);
CREATE TABLE live_activity_tokens (
    token TEXT PRIMARY KEY NOT NULL,
    family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    client_id TEXT NOT NULL,
    activity_id TEXT,
    apns_env TEXT NOT NULL CHECK (apns_env IN ('sandbox', 'production')),
    updated_at TEXT NOT NULL
);
CREATE TABLE pairing_tokens (
    token TEXT PRIMARY KEY NOT NULL,
    family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,
    created_by TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    used_at TEXT,
    used_by TEXT REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE reminders (
    id TEXT PRIMARY KEY NOT NULL,
    child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    rule TEXT NOT NULL,
    next_fire_at TEXT,
    created_at TEXT NOT NULL
);
CREATE TABLE server_meta (
    key TEXT PRIMARY KEY NOT NULL,
    value TEXT NOT NULL
);
INSERT INTO "server_meta" VALUES('server_id','ceca20e6-5ae9-40a6-9300-95de98845418');
CREATE TABLE sessions (
    token TEXT PRIMARY KEY NOT NULL,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL
, device_id TEXT);
CREATE TABLE timers (
    id TEXT PRIMARY KEY NOT NULL,
    child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,
    kind TEXT NOT NULL,
    started_at TEXT NOT NULL,
    started_by TEXT NOT NULL REFERENCES users(id),
    state TEXT NOT NULL DEFAULT 'running',
    stopped_at TEXT,
    updated_at TEXT NOT NULL,
    side TEXT
, paused_at TEXT, paused_seconds INTEGER NOT NULL DEFAULT 0);
